function counts(rows){const out={safe:0,'hold-safe':0,insufficient:0,excluded:0,unsupported:0,'not-evaluated':0,unchangedControls:0,accepted18:0,adaptiveSafe:0,adaptiveHoldSafe:0,adaptiveExcluded:0,unmetExpectations:0};for(const c of rows){const status=outcome(c.after.observation);out[status]++;if(c.conditions.expectation==='unchanged')out.unchangedControls++;if(c.conditions.acceptedControl&&c.conditions.safeAnchor)out.accepted18++;if(c.conditions.revisedAnchor){if(status==='safe')out.adaptiveSafe++;if(status==='hold-safe')out.adaptiveHoldSafe++;if(status==='excluded')out.adaptiveExcluded++;}if(!expectationMet(c.conditions,status))out.unmetExpectations++;}return out;}
async function serve(sourceRoot,dir,relative){
 assert.ok(relative&&!relative.includes('\\')&&!relative.split('/').some(p=>!p||p==='.'||p==='..'),'canonical execution prefix');
 const sharedPrefixes=Object.keys(pngStorage.whitelist).flatMap(build=>[...new Set(['review/'+build,path.posix.normalize(path.posix.join(relative,'../..',build))])].map(prefix=>({prefix:prefix+'/',directory:path.join(root,'review',build)})));
 const server=http.createServer((req,res)=>{try{
  const u=decodeURIComponent(req.url.split('?')[0]);assert.ok(u.startsWith('/')&&!u.includes('\\')&&!u.split('/').some(p=>p==='.'||p==='..'),'canonical request path');
  const p=u.slice(1)+(u.endsWith('/')?'index.html':''),shared=sharedPrefixes.find(s=>p.startsWith(s.prefix));
  const base=p.startsWith(relative+'/')?path.resolve(dir):shared?shared.directory:path.resolve(sourceRoot),suffix=p.startsWith(relative+'/')?p.slice(relative.length+1):shared?p.slice(shared.prefix.length):p,file=path.resolve(base,suffix);
  assert.ok(file.startsWith(base+path.sep),'request stays inside its selected root');
  res.setHeader('Content-Type',file.endsWith('.html')?'text/html; charset=utf-8':file.endsWith('.js')?'text/javascript':file.endsWith('.json')?'application/json':'application/octet-stream');res.end(pngStorage.regular(file));
 }catch{res.writeHead(404).end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));return {server,base:'http://127.0.0.1:'+server.address().port+'/'};
}
function safeFirst(rows){return rows.slice().sort((a,b)=>(Number(!!b.conditions.safeAnchor)*2+Number(b.conditions.expectation==='safe'))-(Number(!!a.conditions.safeAnchor)*2+Number(a.conditions.expectation==='safe')));}
function quickAnchors(m){return specs.layouts.map(layout=>m.cases.find(c=>c.conditions.layout===layout&&c.conditions.safeAnchor&&['safe','hold-safe'].includes(outcome(c.after.observation)))).filter(Boolean);}
function strategyLabel(strategy){const s=String(strategy||''),labels={'editorial-spacing-wrap':'行間・改行の調整','editorial-local-measure':'文字組の幅調整','copy-caption-reflow':'大きな複製と字幕の組直し','side-strip-companion':'補足文字の配置調整','panel-aspect-gap':'コマの比率・間隔の調整','ordered-panel-rows':'読む順を保ったコマの行分け','film-lane-path':'フィルムの通る位置の調整','film-pitch-band':'フィルムの間隔・帯幅の調整','quote-wrap-path':'引用本文の改行・配置の調整','quote-local-typography':'引用本文の行幅の調整','attached-ticket-wrap-path':'券面・半券を保った改行と配置','attached-ticket-padding':'券面内の余白の調整'};return labels[s]||(s==='native-motion-entry-exit-relaxation'?'元の構成（入退場だけ円を通れます）':/native|joint/.test(s)?'元の構成をまとめて移動':/shrink|scale|reduce/.test(s)?'文字サイズの調整':/reflow|typeset|wrap/.test(s)?'改行・行幅の調整':/split|recompose|compose/.test(s)?'まとまり・枠の組替え':/route|path/.test(s)?'動く経路の調整':s);}
function decisionHTML(o){if(!o.adaptiveAPI)return '<p>前回公開版の回避描画です。</p>';if(!o.attempts?.length)return outcome(o)==='safe'?'<p>元の構成のままで、この円を避けられています。</p>':'<p>手動指定などを保持する対照です。</p>';return `<p>採用した配置：${esc(o.decision==='certified'?strategyLabel(o.selectedStrategy)||'なし':'なし')}。${o.composition?`文字倍率 ${esc(o.composition.fontScale??1)}。`:''}${o.safetyScope===relaxedScope?'動いて入退場する要素だけ円の通過を許容し、保持中は円を避けます。':''}${o.failure?'この条件で成立する配置がなく、回避中の候補から除外しました。':''}</p><details><summary>試した配置・採用理由・実寸を見る</summary><table><thead><tr><th>試行順</th><th>方式</th><th>構成・倍率</th><th>実測結果／理由</th></tr></thead><tbody>${o.attempts.map((a,i)=>`<tr><td>${i+1}</td><td>${esc(strategyLabel(a.strategy))}<br><small>${esc(a.strategy)}</small></td><td>${esc(a.variant??'')}／${esc(a.fontScale??1)}<br>候補 ${esc(a.candidateCount??'未記録')}</td><td>${esc(a.status)}${a.reason?'<br>'+esc(a.reason):''}</td></tr>`).join('')}</tbody></table><pre>${esc(JSON.stringify({composition:observationSummary(o),decision:o.decision,failure:o.failure,safetyScope:o.safetyScope,holdWindow:o.holdWindow,relaxedWindows:o.relaxedWindows,realTime:o.time,events:o.renderObservations?.map(r=>({realTime:r.realTime,motionTime:r.motionTime,pass:r.pass,strictCircleClear:r.strictCircleClear,rawCircleClear:r.rawCircleClear,relaxedEvents:(r.relaxedEvents||[]).map(e=>({kind:e.kind,motion:e.motion,phase:e.phase,polygonCount:e.polygons?.length}))}))},null,2))}</pre></details>`;}

function html(m){const status={safe:'動きの全体で円を回避','hold-safe':'保持中は回避／動く入退場要素だけ通過可',excluded:'回避中の候補から除外（この比較では元の歌詞を表示）',insufficient:'制約不足',unsupported:'未対応','not-evaluated':'例外指定の対照'},safe=quickAnchors(m),excluded=m.cases.filter(c=>c.conditions.revisedAnchor&&outcome(c.after.observation)==='excluded');return `<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>配置変更の比較 ${esc(m.build)}</title><style>@font-face{font-family:Fixture;src:url(fixtures/font.otf)}@font-face{font-family:Fixture;src:url(fixtures/font-symbols.ttf);unicode-range:${esc(m.symbolUnicodeRange||'U+25B8')}}body{font:16px Fixture,sans-serif;background:#17202b;color:#eee;margin:16px;overflow-wrap:anywhere}a{color:#acf}button,select,input{font:inherit;max-width:100%}nav{display:flex;flex-wrap:wrap;gap:10px}article{margin:24px 0}figure{margin:0;min-width:0}img,video{width:100%;height:auto;display:block}.pair{display:grid;grid-template-columns:1fr 1fr;gap:8px}.toggle figure:first-child{display:none}.toggle.before figure:first-child{display:block}.toggle.before figure:last-child{display:none}.overlay{position:relative}.overlay figure:last-child{position:absolute;inset:0;opacity:var(--alpha,.5)}.overlay figcaption{display:none}.original{overflow:auto}.original img{width:auto;max-width:none}pre{white-space:pre-wrap;overflow-wrap:anywhere}details{margin:12px 0}summary{cursor:pointer}video{max-width:900px}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{text-align:left;vertical-align:top;padding:6px;border:1px solid #536273}@media(max-width:650px){.pair{grid-template-columns:1fr}table{font-size:13px}}</style><h1>AVOID-006 / ${esc(m.build)}</h1><p>${m.smoke?'ツール予備試験です。受入用の比較ではありません。':'円を避けるための配置変更を比較します。'}変更前は前回公開版の回避描画、変更後は段階的に配置を調整した描画です。まず下の「今回見てほしい8例」から選んでください。</p><p>前後は同じ歌詞・時刻・画面サイズ・入力条件です。配置や文字サイズが変わった場合は、各例に採用結果を示します。前回と同じ18例も確認できます。点線の円は確認用のガイドです。</p><details><summary>技術資料：版・実行条件</summary><p>変更前commit: ${esc(m.before.commit)}。変更後基準: ${esc(m.after.baseCommit)}／HTML SHA-256 ${esc(m.after.sourceSHA256)}。取得 ${esc(m.created)}、${m.repack?'撮影済みの画像と動画を同じhashで再利用。再撮影ではありません。':''}${esc(m.captureEnvironment.browser||'inventory only')}、viewport1500×1500／DPR1。前後は同じseed・固定Noto＋DejaVuフォントです。実行mode・fixture・source hash・時刻等はmanifestと各条件欄に記録します。既存A26 stagedを両版で有効にし、変更後だけlayoutsAAdaptiveを有効にします。通常アプリの既定切替は017、補助マスクは018の対象です。</p></details><nav>${hids.map((h,i)=>`<a href="#${h}">${['通常条件・寸法・文字量','動き・半径切替','手動指定などの保持'][i]}</a>`).join(' ')}<a href="sample.html">同じ時刻で操作する</a><a href="../../../index.html">日本語アプリ（通常設定）</a><a href="../../../en/index.html">英語アプリ（通常設定）</a></nav><section><h2>安全例${m.smoke?'（予備試験）':''}</h2><p>動き全体で円を避ける例と、保持中は避けて動く入退場要素だけ円を通れる例を区別して示します。主要改訂例は1920×1080・円中心(0.5,0.42)・半径0.2で、コマ割りは切替効果なしです（fx:none）。前回と同じ18例と区別し、任意寸法・位置・半径での成立を意味しません。小円や候補除外を安全例の代わりにはしません。</p><h3>今回見てほしい8例</h3><nav>${safe.filter(c=>c.conditions.revisedAnchor).map(c=>`<a href="#${c.id}">${esc(specs.names[c.conditions.layout])}${outcome(c.after.observation)==='hold-safe'?'（保持中は回避）':''}</a>`).join(' ')}</nav><h3>前回と同じ18例</h3><nav>${safe.filter(c=>c.conditions.acceptedControl).map(c=>`<a href="#${c.id}">${esc(specs.names[c.conditions.layout])}</a>`).join(' ')}</nav><h3>位置を変えた入退場通過の確認</h3><nav>${m.cases.filter(c=>c.conditions.passageGroup).map(c=>`<a href="#${c.id}">${esc(specs.names[c.conditions.layout])}・${c.conditions.phase==='hold'?'保持中':c.conditions.phase==='exit'?'退場':'入場'}</a>`).join(' ')}</nav>${excluded.length?`<h3>通常半径で候補除外となった演出</h3><p>成立しない候補は自動選択の対象から外します。この比較では別の演出へ置き換えず、元の歌詞と成立しない理由を表示します。</p><nav>${excluded.map(c=>`<a href="#${c.id}">${esc(specs.displayName(c.conditions.layout))}</a>`).join(' ')}</nav>`:''}</section><p>歌詞の読みやすさと、演出の形や動きが保たれているかを確認してください。</p><details><summary>全条件の集計・確認範囲</summary><p>3項目／実際の比較 ${m.cases.length}組。全時間安全 ${m.counts.safe??0}、保持中のみ安全 ${m.counts['hold-safe']??0}、候補除外 ${m.counts.excluded??0}、対照 ${m.counts['not-evaluated']??0}。改訂8IDの通常半径例：全時間安全 ${m.counts.adaptiveSafe??0}／保持中のみ安全 ${m.counts.adaptiveHoldSafe??0}／候補除外 ${m.counts.adaptiveExcluded??0}。受入期待未達 ${m.counts.unmetExpectations??0}。可読性と演出意図は別途確認してください。${m.smoke?'全固定入力の撮影ではありません。':'可変半径・位置・アスペクト・文字量・各時刻の選択的な比較であり、全直積の撮影ではありません。'}</p></details><label>表示 <select id="mode"><option value="pair">前後を並べる</option><option value="toggle">前後を切り替える</option><option value="overlay">重ね合わせる</option></select></label><button id="toggle">前／後切替</button><label>濃さ <input id="alpha" type="range" min="0" max="1" step=".05" value=".5"></label><button id="size">原寸／画面に合わせる</button><label>画像 <select id="kind"><option value="ui">全体UI</option><option value="original">元Canvas PNG</option></select></label>${Object.entries(m.playback).map(([id,v])=>`<details><summary>${esc(specs.displayName(id))}：同じ時計の前後動画</summary><video controls preload="metadata" src="${v.path}"></video><p>${esc(v.case)}。実描画 ${v.actualFrames}フレーム。${v.passageAudits?.length?'円通過を最初に観測した実時刻 '+esc(v.passageAudits[0].time.toFixed(3))+'秒（'+esc([...new Set(v.passageAudits[0].passes.flatMap(p=>(p.relaxedEvents||[]).map(e=>e.phase)))].join('/'))+'）。同動画の厳守hold監査 '+esc(v.holdAudits?.[0]?.time.toFixed(3))+'秒。連続時間の通過開始点を特定する測定ではありません。':'この動画に円通過の実画素監査はありません。'}</p></details>`).join('')}${hids.map(h=>`<section id="${h}"><h2>${h.endsWith('H01')?'通常半径の改訂例・18対照・半径／位置／文字量':h.endsWith('H02')?'構成と枠・出現／退出・半径区間の切替':'主歌詞／補助／独立装飾と手動・ロック・明示サイズ・OFF'}</h2>${[...new Set(m.cases.filter(c=>c.hid===h).map(c=>c.conditions.layout))].map(layout=>`<details><summary>${esc(specs.displayName(layout))}</summary>${safeFirst(m.cases.filter(c=>c.hid===h&&c.conditions.layout===layout)).map(c=>`${c.conditions.exploratory?'<details><summary>探索条件：'+esc(c.label)+'</summary>':''}<article id="${c.id}"><h3>${esc(c.label)}</h3><p>見る箇所：${esc(c.conditions.look)}</p><p>変化：${esc(c.conditions.change)}</p><p>保持：${esc(c.conditions.preserve)}</p><p>変更後の実測：${esc(status[outcome(c.after.observation)])}。<a href="sample.html?case=${c.id}">この条件で再生・seek</a></p>${decisionHTML(c.after.observation)}<div class="pair">${['before','after'].map(side=>`<figure><figcaption>${side==='before'?'変更前（前回公開版の回避描画）':'変更後（段階的な再配置）'}／t=${c.conditions.time}秒／${c.conditions.W}×${c.conditions.H} <a href="${c[side].original.path}">元PNG</a></figcaption><img loading="lazy" src="${c[side].path}" data-ui="${c[side].path}" data-original="${c[side].original.path}" width="${c[side].width}" height="${c[side].height}" alt="${esc(c.label)} ${side==='before'?'変更前':'変更後'}"></figure>`).join('')}</div><details><summary>条件・前後の実測・診断</summary><pre>${esc(JSON.stringify({conditions:c.conditions,before:observationSummary(c.before.observation),after:observationSummary(c.after.observation)},null,2))}</pre>${['before','after'].map(side=>`<a href="${observationPath(c.id,side)}">${side} gzip JSON</a>`).join(' / ')}</details></article>${c.conditions.exploratory?'</details>':''}`).join('')}</details>`).join('')}</section>`).join('')}<details><summary>技術資料</summary><a href="manifest.json">版・条件</a> <a href="fixtures/cases.json">固定入力</a> <a href="fixtures/source-manifest.json">ソースhash</a> <a href="fixtures/layouts-a-adaptive-test.log">新adaptive自動試験</a> <a href="fixtures/functional-summary.json">実行結果・対象sourceのreceipt</a></details><script>const pairs=[...document.querySelectorAll('.pair')];let original=false;mode.onchange=()=>pairs.forEach(p=>{p.className=mode.value;p.classList.toggle('original',original)});toggle.onclick=()=>pairs.forEach(p=>p.classList.toggle('before'));alpha.oninput=()=>document.body.style.setProperty('--alpha',alpha.value);size.onclick=()=>{original=!original;pairs.forEach(p=>p.classList.toggle('original',original))};kind.onchange=()=>document.querySelectorAll('img').forEach(x=>x.src=x.dataset[kind.value]);function reveal(){if(location.hash){const e=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(e){for(let p=e.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;e.scrollIntoView();}}}addEventListener('hashchange',reveal);reveal();</script></html>`;}
function png(bytes){assert.equal(bytes.subarray(0,8).toString('hex'),'89504e470d0a1a0a','PNG signature');return {width:bytes.readUInt32BE(16),height:bytes.readUInt32BE(20),sha256:sha(bytes)};}
function sources(folder){const out={};for(const p of fs.readdirSync(path.join(folder,'src')).filter(p=>p.endsWith('.js')).sort())out['src/'+p]=sha(read(path.join(folder,'src',p)));return out;}
function fixedBefore(sourceRoot){assert.equal(sha(read(path.join(baseline,'index.html'))),'38b8edf31aaecaa667e1e0248ccc5fa3bbf68380333f819683fdfb6494f3ebe4','pre-adaptive A26 original HTML hash');assert.equal(sha(read(path.join(baseline,'index.html'))),sha(cp.execFileSync('git',['show',baselineCommit+':index.html'],{cwd:root,maxBuffer:16e6})),'fixed pre-adaptive A26 baseline');const expected=cp.execFileSync('git',['ls-tree','--name-only',baselineCommit+':src'],{cwd:root}).toString().trim().split('\n').filter(p=>p.endsWith('.js')).map(p=>'src/'+p).sort();assert.deepEqual(Object.keys(sources(baseline)).sort(),expected,'complete pre-adaptive A26 source inventory');for(const [p,h]of Object.entries(sources(baseline)))assert.equal(h,sha(cp.execFileSync('git',['show',baselineCommit+':'+p],{cwd:root,maxBuffer:16e6})),'fixed baseline source '+p);}
function fontCoverage(font,text){const fonts=Array.isArray(font)?font:[font];cp.execFileSync('python',['-c',"from fontTools.ttLib import TTFont; import sys,json; chars=set(); [chars.update(set().union(*(set(t.cmap) for t in TTFont(p)['cmap'].tables))) for p in sys.argv[1:]]; missing=sorted({ord(c) for c in json.load(sys.stdin) if not c.isspace()}-chars); assert not missing,missing",...fonts],{input:JSON.stringify(text),stdio:['pipe','pipe','pipe']});}
