function comparisonText(markup){return markup.replace(/<script>[\s\S]*?<\/script>/g,'').replace(/<[^>]*>/g,'');}
function decodeSourceEscapes(text){return text.replace(/\\u\{([0-9a-f]{1,6})\}|\\u([0-9a-f]{4})|\\x([0-9a-f]{2})/gi,(_,a,b,c)=>{const cp=parseInt(a||b||c,16);return cp>=32&&!(cp>=127&&cp<=159)&&cp<=0x10ffff?String.fromCodePoint(cp):'';});}
function comparisonInventory(m,matrix){return ['safe','hold-safe','excluded','insufficient','unsupported','not-evaluated'].map(status=>{const observation={time:1.5,trajectory:{units:[{segments:[{start:0,end:4,status:status==='hold-safe'?'safe-hold':status==='safe'?'safe':'insufficient-space'}]}]},safety:status,safetyScope:status==='hold-safe'?relaxedScope:undefined,holdWindow:status==='hold-safe'?{start:.6,end:3.6,clock:'native motionTime'}:undefined,relaxedWindows:status==='hold-safe'?[{phase:'entry',start:0,end:.6},{phase:'exit',start:3.6,end:4}]:undefined,failure:status==='excluded'?'no-certified-composition':undefined,decision:status==='excluded'?'excluded-during-avoidance':['safe','hold-safe'].includes(status)?'certified':undefined,adaptiveAPI:true,attempts:[{strategy:'inventory-only',status:status==='safe'?'certified':'rejected',reason:'inventory only',candidateCount:1}],diagnostics:status==='unsupported'?[{safety:'unsupported'}]:[]};const side={path:'inventory-only.png',width:1500,height:1500,original:{path:'inventory-only-original.png'},observation};return comparisonText(html({...m,playback:{filmstrip:{case:'inventory-only',path:'inventory-only.webm',actualFrames:1,passageAudits:[{time:.2,passes:[{relaxedEvents:[{phase:'entry'}]}]}],holdAudits:[{time:1.5}]},mirror:{case:'inventory-only',path:'inventory-only.webm',actualFrames:1,passageAudits:[],holdAudits:[]}},cases:matrix.map(c=>({id:c.id,hid:c.hid,label:c.label,conditions:conditions(c),before:side,after:side}))}));}).join('\n');}
function buildFixtureFonts(dir,text){write(path.join(dir,'font-text.txt'),text);cp.execFileSync('python',['-m','fontTools.subset','/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc','--font-number=0','--text-file='+path.join(dir,'font-text.txt'),'--output-file='+path.join(dir,'font.otf')]);
 const source='/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',symbols=JSON.parse(cp.execFileSync('python',['-c',"from fontTools.ttLib import TTFont; import sys,json; from fontTools import subset; primary=TTFont(sys.argv[1]); donor=TTFont(sys.argv[2]); cmap=lambda f:set().union(*(set(t.cmap) for t in f['cmap'].tables)); wanted={ord(c) for c in json.load(sys.stdin) if not c.isspace()}; selected=sorted((wanted-cmap(primary))&cmap(donor)); assert selected,'empty symbol inventory'; options=subset.Options(); options.drop_tables.append('FFTM'); sub=subset.Subsetter(options=options); sub.populate(unicodes=selected); sub.subset(donor); donor.save(sys.argv[3]); print(json.dumps(selected))",path.join(dir,'font.otf'),source,path.join(dir,'font-symbols.ttf')],{input:JSON.stringify(text)}));
 const metadata={schema:1,primary:'NotoSansCJK-Regular.ttc face0; unchanged native metrics',symbolSource:'DejaVuSans.ttf',symbolSourceSHA256:sha(read(source)),unicodeRange:symbols.map(c=>'U+'+c.toString(16).toUpperCase()).join(','),codepoints:symbols,purpose:'Explicit same-family glyph fallback for Noto-missing symbols in UI and native Canvas; loaded before fixture measurement'};write(path.join(dir,'font-symbols.json'),metadata);fs.copyFileSync('/usr/share/doc/fonts-noto-cjk/copyright',path.join(dir,'font-license.txt'));fs.copyFileSync('/usr/share/doc/fonts-dejavu-core/copyright',path.join(dir,'font-symbols-license.txt'));return metadata;}
async function waitReady(page){await page.waitForFunction(()=>window.ready||window.failure);assert.equal(await page.evaluate(()=>window.failure),undefined);}
async function settledUIScreenshot(page){assert.deepEqual(page.viewportSize(),{width:1500,height:1500},'fixed UI capture viewport');assert.deepEqual(await page.evaluate(async()=>{await document.fonts.ready;scrollTo(0,0);await new Promise(requestAnimationFrame);return {fonts:document.fonts.status,fixtureFonts:window.fixtureFontsSettled(),playbackFrames:window.playbackFrames,scroll:[scrollX,scrollY],dpr:devicePixelRatio};}),{fonts:'loaded',fixtureFonts:true,playbackFrames:0,scroll:[0,0],dpr:1},'settled paused UI capture');return page.screenshot({fullPage:true,animations:'disabled',caret:'hide',scale:'css'});}
function checkPassageAudits(c,o,audits){assert.ok(Array.isArray(audits),'actual playback passage audit list');for(const a of audits){assert.ok(Number.isFinite(a.time)&&a.time>=0&&a.time<4,'actual playback time');const spec={...c,time:a.time,phase:'playback'},actual={...o,time:a.time,primaryRaster:a.raster,nativeFrameOracle:a.oracle,renderObservations:a.passes};assert.equal(outcome(actual),'hold-safe','passage belongs to actual hold-certified region');assert.ok(a.raster.relaxedConflictPixels>0,'native moving entry/exit pixels actually pass through circle');assert.ok(a.oracle.relaxedConflicts>0,'independent moving-event geometry actually crosses circle');assert.equal(a.raster.time,a.time);assert.equal(a.oracle.region,c.regions?.find(r=>r.start<=a.time&&(r.end===null||a.time<r.end))?.id||'fixture');for(const pass of a.passes){assert.equal(pass.realTime,a.time);assert.ok(Number.isFinite(pass.motionTime),'actual native event motion clock');}assert.ok(a.passes.some(p=>p.relaxedEvents?.length),'actual moving native event');assertHoldFrame(spec,actual);}return audits.length;}
function checkHoldAudits(c,o,audits){assert.ok(Array.isArray(audits),'actual playback hold audit list');for(const a of audits){assert.ok(Number.isFinite(a.time)&&a.time>=0&&a.time<4);const spec={...c,time:a.time,phase:'hold'},actual={...o,time:a.time,primaryRaster:a.raster,nativeFrameOracle:a.oracle,renderObservations:a.passes};assert.equal(a.raster.time,a.time);assert.equal(outcome(actual),'hold-safe');assert.equal(activeSegment(actual)?.region,a.region);for(const p of a.passes)assert.equal(p.realTime,a.time);assertHoldFrame(spec,actual);}return audits.length;}
function requirePassageExamples(rows){for(const group of ['quote-left','ticket-bottom']){const entry=rows.find(r=>r.conditions.passageGroup===group&&r.conditions.requiredPassage),hold=rows.find(r=>r.conditions.passageGroup===group&&r.conditions.phase==='hold');assert.ok(entry&&hold,'actual native passage and same-input hold: '+group);assert.equal(outcome(entry.after.observation),'hold-safe');assert.equal(outcome(hold.after.observation),'hold-safe');assert.ok(entry.after.observation.primaryRaster.relaxedConflictPixels>0);assert.equal(hold.after.observation.primaryRaster.conflictPixels,0);assert.equal(hold.after.observation.primaryRaster.marginConflictPixels,0);assert.deepEqual(entry.after.observation.trajectory,hold.after.observation.trajectory,'same native passage/hold plan');assert.deepEqual(entry.after.observation.nativeParams,hold.after.observation.nativeParams,'same native parameters across passage and hold');}}
function requirePassageVideo(m){if(!m.smoke)assert.ok(Object.values(m.playback).some(v=>v.passageAudits?.length>0),'full comparison requires actual native circle-passage entry/exit video');}
async function checkPlayback(page,minFrames=1){const state=await page.evaluate(()=>({failure:window.failure,frames:window.playbackFrames,passageAudits:window.playbackPassageAudits||[],holdAudits:window.playbackHoldAudits||[],clocks:Object.values(window.observations).map(o=>o.time)}));assert.equal(state.failure,undefined,'playback failed: '+state.failure);assert.ok(Number.isInteger(state.frames)&&state.frames>=minFrames,'actual native playback frames');assert.equal(state.clocks.length,2);assert.equal(state.clocks[0],state.clocks[1],'same actual playback clock');return state;}
